// Progress tracking
const totalRequests = ref(0);
const completedRequests = ref(0);
const fetchProgress = computed(() => 
  totalRequests.value > 0 ? (completedRequests.value / totalRequests.value) * 100 : 0
);

// Settings
const sampleCount = ref(30);
const rateLimitMs = ref(50);
const maxRetries503 = ref(1);

// Parceling configuration
const parcelingMode = ref<ParcelingMode>('smart');
const parcelingModeOptions = [
  { title: 'None (use as-is)', value: 'none' },
  { title: 'Default (fixed chunks)', value: 'default' },
  { title: 'Smart (optimize by timestamps)', value: 'smart' },
