  id: string;
  name: string;
  size: string;
  geometry: RectBounds;
  color: string;
}

const predefinedRegions = ref<TestRegion[]>([
  {
    id: 'small',
    name: 'Small Region',
    size: '0.02° × 0.02°',
    geometry: {
      xmin: -98.8,
      ymin: 40.03,
      xmax: -98.78,
      ymax: 40.05
    },
    color: 'green'
  },
  {
    id: 'medium',
    name: 'Medium Region',
    size: '0.1° × 0.05°',
    geometry: {
      xmin: -98.85,
      ymin: 40.0,
      xmax: -98.75,
