const selectedRegion = ref<TestRegion | null>(null);

// Sample points display state
const showSamplePoints = ref<Record<string, boolean>>({
  small: false,
  medium: false,
  large: false
});

// Actual sample points display state
const showActualSamplePoints = ref<Record<string, boolean>>({
  small: false,
  medium: false,
  large: false
});

// Store sample locations for each region
const regionSampleLocations = ref<Record<string, Array<{ x: number; y: number }>>>({});

// Store actual sample locations from fetch results
const regionActualSampleLocations = ref<Record<string, Array<{ x: number; y: number }>>>({});

// Multi-marker composables for each region
const sampleMarkers: Record<string, ReturnType<typeof useMultiMarker>> = {};

// Multi-marker composables for actual sample points (red)
const actualSampleMarkers: Record<string, ReturnType<typeof useMultiMarker>> = {};

// Sampler for generating sample point locations
const sampler = ref<EsriSampler | null>(null);

// Preset time ranges
