// Computed preset time ranges based on actual available data
// These depend on the parcel size setting for proper parceling
const presetTimeRanges = computed<PresetTimeRange[]>(() => {
  // Get the last available timestamp from esriTimesteps
  const lastTimestamp = esriTimesteps.value.length > 0 
    ? esriTimesteps.value[esriTimesteps.value.length - 1] 
    : Date.now();
  
  const end = new Date(lastTimestamp);
  
  // Use defaultParcelSizeDays converted to milliseconds
  const parcelSizeMs = defaultParcelSizeDays.value * 24 * 60 * 60 * 1000;
  
  // Helper to create range configs with parceling
  const createRangeConfig = (daysBack: number): TimeRangeConfigMultiple => ({
    type: 'multiple',
    dateRange: {
      start: new Date(lastTimestamp - daysBack * 24 * 60 * 60 * 1000),
      end: end
    },
    years: undefined,
    months: undefined,
    weekdays: undefined,
    times: undefined,
    toleranceHours: undefined,
    parcel: false,
    parcelSize: parcelSizeMs
  });
  
  const configs = {
    lastWeek: createRangeConfig(7),
    lastMonth: createRangeConfig(30),
    last3Months: createRangeConfig(90),
    lastYear: createRangeConfig(365),
  };
  
  return [
    {
      id: 'last-week',
      name: 'Last Week',
      description: `Last 7 days of data`,
      ranges: generateTimeRanges(configs.lastWeek),
      config: configs.lastWeek
    },
    {
      id: 'last-month',
      name: 'Last Month',
      description: `Last 30 days of data`,
      ranges: generateTimeRanges(configs.lastMonth),
      config: configs.lastMonth
    },
    {
      id: 'last-3-months',
      name: 'Last 3 Months',
      description: `Last 90 days of data`,
      ranges: generateTimeRanges(configs.last3Months),
      config: configs.last3Months
    },
    {
      id: 'last-year',
      name: 'Last Year',
      description: `Last 365 days of data`,
      ranges: generateTimeRanges(configs.lastYear),
      config: configs.lastYear
    },
    {
      id: 'test-august-2023',
      name: 'Test: Aug 2-4, 2023',
      description: `3 days, 5 times/day (10am, 12pm, 2pm, 4pm, 6pm) ±30min`,
      ranges: generateTimeRanges({...testAugust2023Config, parcel: false, parcelSize: parcelSizeMs}, false),
      config: {...testAugust2023Config, parcel: false, parcelSize: parcelSizeMs}
    },
    {
      id: 'all-data-pattern',
      name: 'All Available Data (Pattern)',
      description: `2023-2025, All months/days, 12pm ±30min`,
      ranges: filterForAllowedDates(generateTimeRanges({...allDataConfig, parcel: false, parcelSize: parcelSizeMs}, false), uniqueDays.value),
      config: {...allDataConfig, parcel: false, parcelSize: parcelSizeMs}
    },
    {
      id: 'many-ranges-pattern',
      name: 'Many Time Ranges (Pattern)',
      description: `2023-2025, Most months/days, 12pm/3pm/9pm ±30min`,
      ranges: filterForAllowedDates(generateTimeRanges({...manyTimeRangesConfig, parcel: false, parcelSize: parcelSizeMs}, false), uniqueDays.value),
      config: {...manyTimeRangesConfig, parcel: false, parcelSize: parcelSizeMs}
    }
  ];
});

const selectedTimeRange = ref<PresetTimeRange | null>(null);

// Store custom time ranges created by the user
const customTimeRanges = ref<PresetTimeRange[]>([]);

// Computed: all available time ranges (presets + custom)
const allTimeRanges = computed(() => [...presetTimeRanges.value, ...customTimeRanges.value]);

// Computed: Actual sample count after grid adjustment
const actualSampleCount = computed(() => {
  if (!selectedRegion.value || !sampler.value) {
    return sampleCount.value;
  }
  
  // Set the geometry for the selected region
  sampler.value.setGeometry(selectedRegion.value.geometry);
  
  // Get the actual sample count that will be used
  const spec = sampler.value.getSamplingSpecificationFromSampleCount(sampleCount.value);
  return spec.count;
});

const sampleCountAdjustmentInfo = computed(() => {
  if (!selectedRegion.value || !sampler.value) {
    return null;
  }
  
  const actual = actualSampleCount.value;
  const requested = sampleCount.value;
  
  if (actual === requested) {
    return null; // No adjustment needed
  }
  
  // Get grid dimensions to explain the adjustment
  sampler.value.setGeometry(selectedRegion.value.geometry);
  const spec = sampler.value.getSamplingSpecificationFromSampleCount(requested);
  
  if (actual < requested) {
    return {
      type: 'reduced' as const,
      message: `Grid constraint: ${spec.lons} × ${spec.lats} = ${actual} samples`,
      reason: 'TEMPO grid spacing cannot accommodate the requested sample count'
    };
  } else {
    return {
      type: 'increased' as const,
      message: `Grid adjusted: ${spec.lons} × ${spec.lats} = ${actual} samples`,
      reason: 'Rounded up to fit TEMPO grid spacing'
    };
  }
});

// Computed
const canFetch = computed(() => {
  return selectedRegion.value !== null && selectedTimeRange.value !== null;
});

// Provide a safe current date for DateTimeRangeSelection
// Use the local singleDateSelected from useUniqueTimeSelection
const currentDate = computed(() => {
  const date = singleDateSelected.value;
  // Check if it's a valid Date object
  if (date && date instanceof Date && !isNaN(date.getTime())) {
    return date;
  }
  // Fallback to current date
  return new Date();
});

// Computed properties for Plotly graph
const plotlyDatasets = computed<PlotltGraphDataSet[]>(() => {
  const result: PlotltGraphDataSet[] = [];
  
  // Convert user datasets to plotly format
  datasets.value.forEach(dataset => {
    result.push(userDatasetToPlotly(dataset));
  });
  
  // Add failed request indicators
  const failedStats = requestStats.value.filter(stat => stat.status === 'error');
  console.log(`plotlyDatasets: Found ${failedStats.length} failed requests out of ${requestStats.value.length} total`);
  
  if (failedStats.length > 0) {
    // Calculate mean value from successful data points for y-position
    const allValues: number[] = [];
    datasets.value.forEach(dataset => {
      Object.values(dataset.samples || {}).forEach(sample => {
        if (sample.value !== null && !isNaN(sample.value)) {
          allValues.push(sample.value);
        }
      });
    });
    const meanValue = nanmean(allValues) ?? 1e16;
    console.log(`plotlyDatasets: Using mean value ${meanValue} for failed request lines, based on ${allValues.length} data points`);
    
    // Create red line segments for each failed time range
    failedStats.forEach((stat, idx) => {
      if (stat.timeRange) {
        const line = {
          x: [new Date(stat.timeRange.start), new Date(stat.timeRange.end)],
          y: [meanValue, meanValue],
          name: `Failed Request ${idx + 1}`,
          datasetOptions: {
            mode: 'lines',
            line: {
              color: 'red',
              width: 3,
              dash: 'solid'
            },
            showlegend: false,
            hovertemplate: `Failed Request<br>Time: %{x}<br>Error: ${stat.errorMessage || stat.errorType || 'Unknown'}<extra></extra>`
          }
        };
        result.push(line);

      }
    });
  }
  
  console.log(`plotlyDatasets: Returning ${result.length} total datasets (${result.length - datasets.value.length} failed request lines)`);
  return result;
});

const plotlyColors = computed(() => {
  return datasets.value.map(d => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return (d as any).region?.color || 'blue';
  });
});

// Methods
function onMapReady(mapInstance: Map) {
  map.value = mapInstance;
  console.log('Map ready');
  
  // Initialize the sampler with service metadata
  const service = store.getTempoDataService('no2' as MoleculeType);
  service.withMetadataCache().then(meta => {
    sampler.value = new EsriSampler(meta);
    console.log('EsriSampler initialized with metadata');
  });
  
  // Initialize sample markers for each region (expected locations)
  predefinedRegions.value.forEach(region => {
    sampleMarkers[region.id] = useMultiMarker(map as Ref<Map | null>, {
      label: `samples-${region.id}`,
      color: region.color,
      fillColor: region.color,
      fillOpacity: 0.6,
      opacity: 1,
      radius: 4,
      outlineColor: '#ffffff',
      scale: 'screen'
    });
    
    // Initialize actual sample markers (red)
    actualSampleMarkers[region.id] = useMultiMarker(map as Ref<Map | null>, {
      label: `actual-samples-${region.id}`,
      color: '#ff0000',
      fillColor: '#ff0000',
      fillOpacity: 0.8,
      opacity: 1,
      radius: 3,
      outlineColor: '#ffffff',
      scale: 'screen'
    });
  });
  
  // Draw all predefined regions on the map
  drawRegionsOnMap();
}

function drawRegionsOnMap() {
  if (!map.value) return;
  
  predefinedRegions.value.forEach(region => {
    // Add region as a rectangle on the map
    if (map.value?.getSource(`region-${region.id}`)) {
      return; // Already added
    }
    
    map.value?.addSource(`region-${region.id}`, {
      type: 'geojson',
      data: {
        type: 'Feature',
        geometry: {
          type: 'Polygon',
          coordinates: [[
            [region.geometry.xmin, region.geometry.ymin],
            [region.geometry.xmax, region.geometry.ymin],
            [region.geometry.xmax, region.geometry.ymax],
            [region.geometry.xmin, region.geometry.ymax],
            [region.geometry.xmin, region.geometry.ymin]
          ]]
        },
        properties: {}
      }
    });
    
    map.value?.addLayer({
      id: `region-${region.id}-fill`,
      type: 'fill',
      source: `region-${region.id}`,
      paint: {
        'fill-color': region.color,
        'fill-opacity': 0.2
      }
    });
    
    map.value?.addLayer({
      id: `region-${region.id}-outline`,
      type: 'line',
      source: `region-${region.id}`,
      paint: {
        'line-color': region.color,
        'line-width': 2
      }
    });
  });
}

function selectRegion(region: TestRegion) {
  selectedRegion.value = region;
  
  // Update map opacity to highlight selected region
  if (map.value) {
    predefinedRegions.value.forEach(r => {
      const opacity = r.id === region.id ? 0.4 : 0.1;
      const lineWidth = r.id === region.id ? 3 : 2;
      map.value?.setPaintProperty(`region-${r.id}-fill`, 'fill-opacity', opacity);
      map.value?.setPaintProperty(`region-${r.id}-outline`, 'line-width', lineWidth);
    });
    
    // Fly to the selected region
    const centerLng = (region.geometry.xmin + region.geometry.xmax) / 2;
    const centerLat = (region.geometry.ymin + region.geometry.ymax) / 2;
    map.value.flyTo({
      center: [centerLng, centerLat],
      zoom: region.id === 'large' ? 7 : region.id === 'medium' ? 9 : 11,
      duration: 1000
    });
  }
}

function selectTimeRange(preset: PresetTimeRange) {
  selectedTimeRange.value = preset;
}

function handleCustomTimeRangeChange(
  ranges: MillisecondRange[],
  selectionType: string,
  customName: string,
  config: TimeRangeConfig
) {
  // Create a new custom time range from the selection
  const customRange: PresetTimeRange = {
    id: `custom-${Date.now()}`,
    name: customName || `Custom Range ${customTimeRanges.value.length + 1}`,
    description: selectionType === 'single' 
      ? 'Single date selection' 
      : `Pattern: ${ranges.length} time range(s)`,
    ranges: ranges,
    config: config
  };
  
  // Add to custom ranges
  customTimeRanges.value.push(customRange);
  
  // Automatically select this new range
  selectedTimeRange.value = customRange;
  
  // Switch to presets tab to show it's selected
  timeRangeTab.value = 'presets';
  
  console.log(`Custom time range created: ${customRange.name} with ${ranges.length} ranges`);
}

function removeCustomTimeRange(id: string) {
  const index = customTimeRanges.value.findIndex(r => r.id === id);
  if (index >= 0) {
    customTimeRanges.value.splice(index, 1);
    // If this was selected, clear selection
    if (selectedTimeRange.value?.id === id) {
      selectedTimeRange.value = null;
    }
  }
}

function toggleSamplePoints(region: TestRegion) {
  if (!map.value) return;
  
  const show = showSamplePoints.value[region.id];
  const marker = sampleMarkers[region.id];
  
  if (!marker) {
    console.warn(`No marker initialized for region ${region.id}`);
    return;
  }
  
  if (show) {
    // Always regenerate sample points to reflect current sample count
    if (!sampler.value) {
      console.warn('Sampler not initialized yet. Please wait for metadata to load.');
      showSamplePoints.value[region.id] = false; // Reset checkbox
      return;
    }
    
    // Set the geometry for this region
    sampler.value.setGeometry(region.geometry);
    
    // Get sample locations based on the current sample count setting
    const locations = sampler.value.getSampleLocationsGrid(sampleCount.value);
    
    // Update the stored locations
    regionSampleLocations.value[region.id] = locations;
    
    marker.addMarkers(locations);
    console.log(`Showing ${locations.length} expected sample points for ${region.name} (sample count: ${sampleCount.value})`);
  } else {
    // Hide sample points
    marker.clearMarkers();
    console.log(`Hiding expected sample points for ${region.name}`);
  }
}

function toggleActualSamplePoints(region: TestRegion) {
  if (!map.value) return;
  
  const show = showActualSamplePoints.value[region.id];
  const marker = actualSampleMarkers[region.id];
  
  if (!marker) {
    console.warn(`No actual marker initialized for region ${region.id}`);
    return;
  }
  
  if (show) {
    // Get actual sample locations from fetch results
    const locations = regionActualSampleLocations.value[region.id];
    
    if (!locations || locations.length === 0) {
      console.warn(`No actual sample locations available for ${region.name}. Fetch data first.`);
      showActualSamplePoints.value[region.id] = false; // Reset checkbox
      return;
    }
    
    marker.addMarkers(locations);
    console.log(`Showing ${locations.length} actual sample points (red) for ${region.name}`);
  } else {
    // Hide actual sample points
    marker.clearMarkers();
    console.log(`Hiding actual sample points for ${region.name}`);
  }
}

async function fetchData() {
  if (!canFetch.value || !selectedRegion.value || !selectedTimeRange.value) return;
  
  fetching.value = true;
  
  // Clear previous stats before starting new fetch
  requestStats.value = [];
  
  // Reset progress tracking
  completedRequests.value = 0;
  
  // Track overall timing
  const overallStartTime = performance.now();
  
  try {
    const service = store.getTempoDataService('no2' as MoleculeType);
    await service.withMetadataCache();
    
    // Set rate limit and retry limit from UI controls
    service.setRateLimit(rateLimitMs.value);
    service.setRetryLimit(maxRetries503.value);
    
    // Configure parceling settings
    service.setParcelingMode(parcelingMode.value);
    service.setDefaultParcelSize(defaultParcelSizeDays.value * 24 * 60 * 60 * 1000); // Convert days to ms
    service.setMaxSamplesPerRequest(maxSamplesPerRequest.value);
    service.setSafetyMargin(safetyMargin.value);
    
    // Pass in the available timestamps for smart parceling
    service.setAvailableTimestamps(esriTimesteps.value);
    
    // Use the selected time range (either preset or custom)
    // The ranges are already chunked via the parcel option in generateTimeRanges
    const timeRanges: { start: number; end: number }[] = selectedTimeRange.value.ranges;
    
    // Set total requests for progress tracking
    totalRequests.value = timeRanges.length;
    
    // Log sample count information
    const adjustmentInfo = sampleCountAdjustmentInfo.value;
    if (adjustmentInfo) {
      console.log(`%c⚠️  Sample Count Adjusted`, 'color: #FF9800; font-weight: bold; font-size: 12px');
      console.log(`   Requested: ${sampleCount.value}`);
      console.log(`   Actual:    ${actualSampleCount.value}`);
      console.log(`   Reason:    ${adjustmentInfo.reason}`);
      console.log(`   Grid:      ${adjustmentInfo.message}`);
    } else {
      console.log(`Using sample count: ${sampleCount.value}`);
    }
    
    console.log(`Fetching data for ${timeRanges.length} time chunks`);
    
    // Create progress callback
    const onProgress = (stats: RequestStats, completed: number, _total: number) => {
      // Add stats in real-time
      requestStats.value.push(stats);
      completedRequests.value = completed;
      // console.log(`Progress: ${completed}/${total} - ${stats.status === 'success' ? 'Success' : 'Error'}`);
    };
    
    // Fetch timeseries data with progress callback
    const result = await service.fetchTimeseriesData(
      selectedRegion.value.geometry,
      timeRanges,
      { 
        sampleCount: sampleCount.value,
        onProgress: onProgress
      }
    );
    
    // Stats are already added via the progress callback, no need to add them again
    console.log(`Fetch complete. Total stats collected: ${requestStats.value.length}`);
    
    // Store actual sample locations for this region (from fetched data)
    if (result.locations && result.locations.length > 0) {
      regionActualSampleLocations.value[selectedRegion.value.id] = result.locations;
      console.log(`Stored ${result.locations.length} actual sample locations for ${selectedRegion.value.name}`);
      
      // If actual sample points are currently showing for this region, update them
      if (showActualSamplePoints.value[selectedRegion.value.id]) {
        const marker = actualSampleMarkers[selectedRegion.value.id];
        if (marker) {
          marker.clearMarkers();
          marker.addMarkers(result.locations);
          console.log(`Updated displayed actual sample points (red) with fetched data locations`);
        }
      }
    }
    
    // Create dataset for display
    const dataset: UserDataset = {
      id: v4(),
      name: `${selectedRegion.value.name} - ${selectedTimeRange.value.name}`,
      samples: result.values,
      errors: result.errors,
      timeRange: {
        id: v4(),
        name: selectedTimeRange.value.name,
        description: selectedTimeRange.value.description,
        range: timeRanges.length === 1 ? timeRanges[0] : timeRanges,
        type: 'single'
      },
      region: {
        ...selectedRegion.value.geometry,
        id: selectedRegion.value.id,
        name: selectedRegion.value.name,
        color: selectedRegion.value.color
      },
      molecule: 'NO₂',
      locations: result.locations
    };
    
    datasets.value.push(dataset);
    
    console.log(`Fetched ${Object.keys(result.values).length} data points`);
    
    // ============================================================================
    // LOAD TEST SUMMARY - Comprehensive Statistics
    // ============================================================================
    const overallEndTime = performance.now();
    const totalDuration = overallEndTime - overallStartTime;
    
    // Calculate statistics from requestStats
    const allStats = requestStats.value;
    const successfulRequests = allStats.filter(s => s.status === 'success');
    const failedRequests = allStats.filter(s => s.status === 'error');
    const error503Count = allStats.filter(s => s.errorType === '503').length;
    const error400Count = allStats.filter(s => s.errorType === '400').length;
    const errorOtherCount = allStats.filter(s => s.errorType === 'other' && s.status === 'error').length;
    
    // Break down retried requests by success/failure
    const retriedRequests = allStats.filter(s => s.retried);
    const retriedSuccessful = retriedRequests.filter(s => s.status === 'success').length;
    const retriedFailed = retriedRequests.filter(s => s.status === 'error').length;
    const retriedFrom503Successful = allStats.filter(s => s.retriedFrom503 && s.status === 'success').length;
    const retriedFrom503Failed = allStats.filter(s => s.retriedFrom503 && s.status === 'error').length;
    
    // Timing statistics
    const durations = allStats.map(s => s.duration);
    const totalRequestTime = durations.reduce((sum, d) => sum + d, 0);
    const avgDuration = durations.length > 0 ? totalRequestTime / durations.length : 0;
    const minDuration = durations.length > 0 ? Math.min(...durations) : 0;
    const maxDuration = durations.length > 0 ? Math.max(...durations) : 0;
    
    // Sample statistics
    const totalSamplesFetched = successfulRequests.reduce((sum, s) => sum + s.sampleCount, 0);
    const expectedSamplesPerRequest = sampleCount.value;
    const actualTimeRangesFetched = allStats.length;
    const inputTimeRanges = timeRanges.length;
    
    // Data points - actual results returned
    const dataPointsReturned = Object.keys(result.values).length; // Unique timestamps in returned data
    const locationsCount = result.locations?.length || 0;
    
    // Print styled summary
    console.log('%c╔════════════════════════════════════════════════════════════════╗', 'color: #4CAF50; font-weight: bold');
    console.log('%c║                    LOAD TEST SUMMARY                          ║', 'color: #4CAF50; font-weight: bold');
    console.log('%c╚════════════════════════════════════════════════════════════════╝', 'color: #4CAF50; font-weight: bold');
    
    console.log('%c\n⏱️  TIMING', 'color: #2196F3; font-weight: bold; font-size: 14px');
    console.log(`   Total Duration:        ${(totalDuration / 1000).toFixed(2)}s`);
    console.log(`   Request Time (sum):    ${(totalRequestTime / 1000).toFixed(2)}s`);
    console.log(`   Avg Request Duration:  ${avgDuration.toFixed(0)}ms`);
    console.log(`   Min Request Duration:  ${minDuration.toFixed(0)}ms`);
    console.log(`   Max Request Duration:  ${maxDuration.toFixed(0)}ms`);
    
    console.log('%c\n📊 REQUEST STATISTICS', 'color: #FF9800; font-weight: bold; font-size: 14px');
    console.log(`   Input Time Ranges:     ${inputTimeRanges}`);
    console.log(`   Actual Requests Made:  ${actualTimeRangesFetched}`);
    console.log(`   Successful Requests:   ${successfulRequests.length} (${((successfulRequests.length / actualTimeRangesFetched) * 100).toFixed(1)}%)`);
    console.log(`   Failed Requests:       ${failedRequests.length} (${((failedRequests.length / actualTimeRangesFetched) * 100).toFixed(1)}%)`);
    
    if (retriedRequests.length > 0) {
      console.log(`   Retried Requests:      ${retriedRequests.length} total`);
      console.log(`     → Succeeded:         ${retriedSuccessful}`);
      console.log(`     → Failed:            ${retriedFailed}`);
      if (retriedFrom503Successful > 0 || retriedFrom503Failed > 0) {
        console.log(`   Retried from 503:      ${retriedFrom503Successful + retriedFrom503Failed} total`);
        console.log(`     → Succeeded:         ${retriedFrom503Successful}`);
        console.log(`     → Failed:            ${retriedFrom503Failed}`);
      }
    }
    
    if (failedRequests.length > 0) {
      console.log('%c\n⚠️  ERROR BREAKDOWN', 'color: #F44336; font-weight: bold; font-size: 14px');
      console.log(`   503 Errors:            ${error503Count}`);
      console.log(`   400 Errors:            ${error400Count}`);
      console.log(`   Other Errors:          ${errorOtherCount}`);
    }
    
    console.log('%c\n📈 SAMPLE STATISTICS', 'color: #9C27B0; font-weight: bold; font-size: 14px');
    console.log(`   Expected Samples/Time: ${expectedSamplesPerRequest}`);
    if (parcelingMode.value === 'smart' && result.expectedTotalSamples !== undefined) {
      // Use the actual expected total from the service (counts timestamps in time ranges)
      console.log(`   Expected Total Count:  ${result.expectedTotalSamples.toLocaleString()}`);
    }
    console.log(`   Total Samples Fetched: ${totalSamplesFetched.toLocaleString()}`);
    console.log(`   Avg Samples/Request:   ${actualTimeRangesFetched > 0 ? (totalSamplesFetched / actualTimeRangesFetched).toFixed(0) : 0}`);
    
    console.log('%c\n🎯 DATA RESULTS', 'color: #00BCD4; font-weight: bold; font-size: 14px');
    console.log(`   Data Points Returned:  ${dataPointsReturned} (unique timestamps)`);
    console.log(`   Unique Locations:      ${locationsCount}`);
    console.log(`   Total Data Values:     ${(dataPointsReturned * locationsCount).toLocaleString()}`);
    
    // Use expected total from service if available (smart mode)
    if (result.expectedTotalSamples !== undefined) {
      console.log(`   Expected Samples:      ${result.expectedTotalSamples.toLocaleString()}`);
      console.log(`   Actual Samples:        ${totalSamplesFetched.toLocaleString()}`);
      console.log(`   Sample Efficiency:     ${((totalSamplesFetched / result.expectedTotalSamples) * 100).toFixed(1)}%`);
    } else {
      // For non-smart modes, we don't have an accurate prediction
      console.log(`   Actual Samples:        ${totalSamplesFetched.toLocaleString()}`);
    }
    
    console.log('%c\n⚙️  CONFIGURATION', 'color: #607D8B; font-weight: bold; font-size: 14px');
    console.log(`   Parceling Mode:        ${parcelingMode.value}`);
    console.log(`   Sample Count:          ${sampleCount.value}`);
    console.log(`   Rate Limit:            ${rateLimitMs.value}ms`);
    console.log(`   Max Retries:           ${maxRetries503.value}`);
    if (parcelingMode.value === 'smart') {
      console.log(`   Max Samples/Request:   ${maxSamplesPerRequest.value}`);
      console.log(`   Safety Margin:         ${(safetyMargin.value * 100).toFixed(0)}%`);
    } else if (parcelingMode.value === 'default') {
      console.log(`   Parcel Size:           ${defaultParcelSizeDays.value} days`);
    }
    
    console.log('%c\n' + '═'.repeat(64), 'color: #4CAF50');
    
    // Add a fake failed request for testing visualization
    if (timeRanges.length > 0 && requestStats.value.length > 0) {
      // Pick a time range in the middle of the data
      const middleIndex = Math.floor(timeRanges.length / 2);
      const fakeFailedRange = timeRanges[middleIndex];
      
      const _fakeFailedStat: RequestStats = {
        status: 'error',
        statusCode: 400,
        errorType: '400',
        errorMessage: 'FAKE ERROR FOR TESTING: This is a simulated failed request to test visualization',
        duration: 1500,
        sampleCount: sampleCount.value,
        retried: false,
        timestamp: fakeFailedRange.start,
        timeRange: fakeFailedRange,
        url: 'https://fake-test-url.example.com'
      };
      
      // requestStats.value.push(fakeFailedStat);
      console.log('Added fake failed request for testing visualization');
    }
  } catch (error) {
    console.error('Error fetching data:', error);
    alert('Error fetching data. Check console for details.');
  } finally {
    fetching.value = false;
  }
}

// Generated by Copilot - Dry run function to generate URLs without fetching
async function dryRunData() {
  if (!canFetch.value || !selectedRegion.value || !selectedTimeRange.value) return;
  
  fetching.value = true;
  
  try {
    const service = store.getTempoDataService('no2' as MoleculeType);
    await service.withMetadataCache();
    
    // Configure parceling settings
    service.setParcelingMode(parcelingMode.value);
    service.setDefaultParcelSize(defaultParcelSizeDays.value * 24 * 60 * 60 * 1000);
    service.setMaxSamplesPerRequest(maxSamplesPerRequest.value);
    service.setSafetyMargin(safetyMargin.value);
    service.setAvailableTimestamps(esriTimesteps.value);
    
    // Enable dry run mode
    service.setDryRun(true);
    
    const timeRanges: { start: number; end: number }[] = selectedTimeRange.value.ranges;
    
    console.log('%c╔════════════════════════════════════════════════════════════════╗', 'color: #FF9800; font-weight: bold');
    console.log('%c║                      DRY RUN MODE                              ║', 'color: #FF9800; font-weight: bold');
    console.log('%c╚════════════════════════════════════════════════════════════════╝', 'color: #FF9800; font-weight: bold');
    console.log(`\nGenerating URLs for ${timeRanges.length} time chunks...`);
    
    // "Fetch" with dry run enabled
    await service.fetchTimeseriesData(
      selectedRegion.value.geometry,
      timeRanges,
      {
        sampleCount: actualSampleCount.value,
        dryRun: true
      }
    );
    
    // Get the generated URLs
    const urls = service.getRequestUrls();
    
    console.log('%c\n📋 GENERATED URLs:', 'color: #FF9800; font-weight: bold; font-size: 14px');
    console.log(`   Total URLs: ${urls.length}`);
    console.log('\nAll Request URLs (JSON):');
    console.log({url: urls});
    
    console.log('%c\n✅ Dry run complete - no requests were made', 'color: #4CAF50; font-weight: bold');
    
    // Disable dry run mode
    service.setDryRun(false);
    
    // alert(`Dry run complete! Generated ${urls.length} URLs.\nCheck console for details.`);
  } catch (error) {
    console.error('Error in dry run:', error);
    alert('Error in dry run. Check console for details.');
  } finally {
    fetching.value = false;
  }
}

// Note: splitTimeRanges is no longer needed - parceling is handled by generateTimeRanges

function clearStatistics() {
  requestStats.value = [];
  datasets.value = [];
  totalRequests.value = 0;
  completedRequests.value = 0;
  selectedTimeRangeForMap.value = null;
}

function handleTimeRangeSelect(stat: RequestStats) {
  selectedTimeRangeForMap.value = stat;
  
  // Update the map timestamp to show the selected time
  if (stat.timeRange) {
    // Set the map time to the start of the selected time range
    mapTimestamp.value = stat.timeRange.start;
    console.log(`Selected time range: ${new Date(stat.timeRange.start).toISOString()} - ${new Date(stat.timeRange.end).toISOString()}`);
  }
}

function handleGraphClick(point: {x: Date | number | string | null, y: number, customdata: unknown}) {
  console.log("handleGraphClick called with:", point);
  // Update the map timestamp when a point on the graph is clicked
  let timestamp: number | null = null;
  
  if (point.x instanceof Date) {
    timestamp = point.x.getTime();
  } else if (typeof point.x === 'number') {
    timestamp = point.x;
  } else if (typeof point.x === 'string') {
    // Parse string date
    const parsed = new Date(point.x);
    if (!isNaN(parsed.getTime())) {
      timestamp = parsed.getTime();
    }
  }
  
  console.log("Processed timestamp:", timestamp, "from point.x type:", typeof point.x);
  if (timestamp) {
    mapTimestamp.value = timestamp;
    console.log(`Graph point clicked: ${new Date(timestamp).toISOString()}, value: ${point.y}`);
  } else {
    console.warn("Could not extract timestamp from point.x:", point.x);
  }
}

function jitterRegions() {
  // Add small random offset to each region's bounds
  // Jitter amount: ±0.001 to ±0.005 degrees (roughly 100-500 meters)
  const jitterAmount = 0.1;
  
  predefinedRegions.value.forEach(region => {
    const dx = (Math.random() - 0.5) * 2 * jitterAmount;
    const dy = (Math.random() - 0.5) * 2 * jitterAmount;
    
    region.geometry.xmin += dx;
    region.geometry.xmax += dx;
    region.geometry.ymin += dy;
    region.geometry.ymax += dy;
    
    console.log(`Jittered ${region.name} by (${dx.toFixed(5)}, ${dy.toFixed(5)})`);
  });
  
  // Clear expected sample locations since regions have moved
  regionSampleLocations.value = {};
  // Note: Keep actual sample locations - they're from real data
  
  // Update map visualization
  if (map.value) {
    predefinedRegions.value.forEach(region => {
      const source = map.value?.getSource(`region-${region.id}`);
      if (source && 'setData' in source && typeof source.setData === 'function') {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        (source as any).setData({
          type: 'Feature',
          geometry: {
            type: 'Polygon',
            coordinates: [[
              [region.geometry.xmin, region.geometry.ymin],
              [region.geometry.xmax, region.geometry.ymin],
              [region.geometry.xmax, region.geometry.ymax],
              [region.geometry.xmin, region.geometry.ymax],
              [region.geometry.xmin, region.geometry.ymin]
            ]]
          },
          properties: {}
        });
      }
    });
  }
  
  console.log('Regions jittered for cache busting');
}

// Watch for parcel size changes and update selected preset if needed
watch(defaultParcelSizeDays, () => {
  // If a preset time range is selected, update it with the new parcel size
  if (selectedTimeRange.value) {
    const presetId = selectedTimeRange.value.id;
    
    // Check if this is a preset (not a custom range)
    const updatedPreset = presetTimeRanges.value.find(p => p.id === presetId);
    
    if (updatedPreset) {
      // Update the selected range with the newly generated ranges
      selectedTimeRange.value = updatedPreset;
      console.log(`Updated selected time range "${updatedPreset.name}" with ${updatedPreset.ranges.length} ranges for parcel size: ${defaultParcelSizeDays.value} days`);
    }
  }
});

// Watch for sample count changes and update displayed sample points automatically
watch(sampleCount, () => {
  // Update all visible sample point displays
  predefinedRegions.value.forEach(region => {
    if (showSamplePoints.value[region.id]) {
      // Regenerate and update the displayed points
      if (sampler.value) {
        sampler.value.setGeometry(region.geometry);
        const locations = sampler.value.getSampleLocationsGrid(sampleCount.value);
        regionSampleLocations.value[region.id] = locations;
        
        const marker = sampleMarkers[region.id];
        if (marker) {
          marker.clearMarkers();
          marker.addMarkers(locations);
          console.log(`Updated sample points for ${region.name}: ${locations.length} locations (sample count: ${sampleCount.value})`);
        }
      }
    }
  });
});

// Note: Timestamps are now fetched directly via useEsriTimesteps composable
// No need for onMounted initialization
